window.RP_SESSION={"id":"S-e8d9b2952233","messages":[{"id":"RP-0155559","time":"2026-05-12T18:00:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"···","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155560","time":"2026-05-12T18:00:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"···","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155561","time":"2026-05-12T18:00:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"···","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155562","time":"2026-05-12T18:06:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그리움에 응어리···.\n\n그리움, 그리···.\n\n솔이 써내려가던 양피지 위의 깃펜이 멈췄다. 잉크가 송글송글 맺히며 양피지를 적셨다.\n\n길드 대장간 근처, 바위 위에 앉아 강을 배경으로 한 모습이었다.","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155563","time":"2026-05-12T18:14:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 전혀 모르겠는데. ”\n\n한숨을 내쉬었다. 정리해야할 두번째 감정이 그리움. 노트에 정의를 적어보고, 그것을 시로 엮어낸다.\n\n그러나, 그것을 정리하는데에 골머리를 앓고 있던 것은, 직접 정의를 적어내야 하는 솔이었다.","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155564","time":"2026-05-12T18:24:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"에휴. 양피지에 끼적끼적.","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155565","time":"2026-05-12T18:42:00+09:00","room":"RP","name":"Seon \"South Foot\"","profile":"Seon \"South Foot\"","identity":"unresolved","type":"dialogue","body":"뭐가?","characters":[]},{"id":"RP-0155566","time":"2026-05-12T19:09:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그리움이 정확히 뭔지가.\n\n다시금 깃펜을 잉크에 닿게 만들었다.\n\n찔금···.","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155567","time":"2026-05-12T19:27:00+09:00","room":"RP","name":"Seon \"South Foot\"","profile":"Seon \"South Foot\"","identity":"unresolved","type":"dialogue","body":"왜?","characters":[]},{"id":"RP-0155568","time":"2026-05-12T19:32:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"··· 아직까지도 이해하지 못한 것을 이해하기 위해서.","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155569","time":"2026-05-12T20:02:00+09:00","room":"RP","name":"Seon \"South Foot\"","profile":"Seon \"South Foot\"","identity":"unresolved","type":"dialogue","body":"무엇을?","characters":[]},{"id":"RP-0155570","time":"2026-05-12T20:11:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"감정을. 제대로 정의할 수 없는 이 답답함을.","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155571","time":"2026-05-12T20:15:00+09:00","room":"RP","name":"Seon \"South Foot\"","profile":"Seon \"South Foot\"","identity":"unresolved","type":"dialogue","body":"그렇다면, 다시 왜?","characters":[]},{"id":"RP-0155572","time":"2026-05-12T20:19:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"··· 무언가를 제대로 마주하기 위해서?\n\n솔의 깃펜이 글을 써내려가던 도중 멈췄다. 누군가를 그리워한다, 사랑한다.\n\n경험해보고 싶고, 이것을 이해해보고 싶다.","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155573","time":"2026-05-12T20:20:00+09:00","room":"RP","name":"Seon \"South Foot\"","profile":"Seon \"South Foot\"","identity":"unresolved","type":"dialogue","body":"...\n\n...\n\n...\n\n...누구를?","characters":[]},{"id":"RP-0155574","time":"2026-05-12T21:59:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-0155575","time":"2026-05-12T21:59:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
